<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import { anularLectura, listarLecturas, obtenerLectura, registrarLectura } from '../services/lecturas'
import type { Lectura, Option } from '../interfaces/lecturas.interface'
const route=useRoute(),router=useRouter(),rows=ref<Lectura[]>([]),distritos=ref<Option[]>([]),rutas=ref<Option[]>([]),observaciones=ref<Option[]>([]),dinamicas=ref<Option[]>([]),loading=ref(false),saving=ref(false),modal=ref(false),detail=ref<Lectura|null>(null),error=ref(''),success=ref(''),files=ref<File[]>([]),total=ref(0),lastPage=ref(1),progress=reactive({registradas:0,total:0});const filters=reactive({criterio:'',distrito_id:'',ruta_id:'',estado:'pendiente',page:1});const form=reactive({legible:true,lectura:'',observacion_id:'',detalle:'',latitud:'',longitud:'',dinamicas:[] as number[]});const percent=computed(()=>progress.total?Math.round(progress.registradas*100/progress.total):0),current=computed(()=>Number(form.lectura||0)),consumption=computed(()=>detail.value&&form.legible?Math.max(0,current.value-detail.value.lectura_anterior):0),atypical=computed(()=>!!(detail.value&&form.legible&&((detail.value.minimo_esperado!==undefined&&current.value<detail.value.minimo_esperado)||(detail.value.maximo_esperado!==undefined&&current.value>detail.value.maximo_esperado))))
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarLecturas(filters);rows.value=r.data;distritos.value=r.distritos;rutas.value=r.rutas;observaciones.value=r.observaciones;dinamicas.value=r.dinamicas;total.value=r.total;lastPage.value=r.last_page;Object.assign(progress,r.avance)}catch(e){error.value=msg(e)}finally{loading.value=false}}async function open(id:number){error.value='';try{detail.value=await obtenerLectura(id);Object.assign(form,{legible:true,lectura:'',observacion_id:'',detalle:'',latitud:'',longitud:'',dinamicas:[]});files.value=[];modal.value=true;router.replace({query:{...route.query,lectura:String(id)}});navigator.geolocation?.getCurrentPosition(p=>{form.latitud=String(p.coords.latitude);form.longitud=String(p.coords.longitude)})}catch(e){error.value=msg(e)}}function close(){modal.value=false;detail.value=null;const q={...route.query};delete q.lectura;router.replace({query:q})}function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[]).slice(0,5)}function toggle(id:number){form.dinamicas=form.dinamicas.includes(id)?form.dinamicas.filter(x=>x!==id):[...form.dinamicas,id]}function validate(){if(form.legible&&(!form.lectura||current.value<0))return'Ingrese una lectura numérica válida.';if(form.legible&&detail.value&&current.value<detail.value.lectura_anterior)return'La lectura no puede ser menor que la anterior.';if(!form.legible&&!form.observacion_id)return'Seleccione el impedimento de lectura.';if((!form.legible||atypical.value)&&!files.value.length)return'Debe adjuntar al menos una fotografía.';return''}async function submit(next=false){if(!detail.value)return;const issue=validate();if(issue){error.value=issue;return}saving.value=true;error.value='';try{const data=new FormData();data.append('legible',form.legible?'1':'0');data.append('lectura',form.legible?form.lectura:'0');data.append('observacion_id',form.observacion_id);data.append('detalle',form.detalle);data.append('latitud',form.latitud);data.append('longitud',form.longitud);form.dinamicas.forEach(x=>data.append('dinamicas[]',String(x)));files.value.forEach(x=>data.append('fotografias[]',x));const r=await registrarLectura(detail.value.id,data);success.value='Lectura registrada correctamente.';close();await load(filters.page);if(next&&r.siguiente_id)await open(r.siguiente_id)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function remove(x:Lectura){if(!confirm(`¿Anular la lectura del medidor ${x.medidor}?`))return;try{await anularLectura(x.id);success.value='Lectura anulada correctamente.';await load(filters.page)}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(async()=>{await load();const id=Number(route.query.lectura);if(id)await open(id)})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Registro de lecturas</nav><header class="hero"><div class="mark">L</div><div><small>EVAN · MEDICIÓN</small><h1>Registro de lecturas</h1><p>Captura de campo, incidencias, evidencias y dinámica catastral.</p></div><div class="advance"><b>{{percent}}%</b><span>{{progress.registradas}} de {{progress.total}}</span><i><em :style="{width:percent+'%'}"></em></i></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Medidor, suministro o cliente" @keyup.enter="load(1)"></label><label>Distrito<select v-model="filters.distrito_id"><option value="">Todos</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Ruta<select v-model="filters.ruta_id"><option value="">Todas</option><option v-for="x in rutas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="pendiente">Pendientes</option><option value="registrado">Registradas</option><option value="">Todas</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando lecturas…</div><div v-else-if="!rows.length" class="empty">No existen lecturas en la selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="{done:x.registrado}"><header><span>{{x.ruta}} · Sec. {{x.secuencia}}</span><em>{{x.registrado?'Registrada':'Pendiente'}}</em></header><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><dl><div><dt>Medidor</dt><dd>{{x.medidor}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro}}</dd></div><div><dt>Lectura anterior</dt><dd>{{x.lectura_anterior}}</dd></div><div><dt>Promedio</dt><dd>{{x.consumo_promedio}} m³</dd></div></dl><div v-if="x.registrado" class="reading"><b>{{x.lectura_actual}}</b><span>Consumo {{x.consumo}} m³ · {{x.fecha_lectura}}</span></div><footer><button @click="open(x.id)">{{x.registrado?'Ver detalle':'Tomar lectura'}}</button><button v-if="x.registrado" class="remove" @click="remove(x)">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}} · {{total}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal&&detail" class="backdrop" @mousedown.self="close"><form class="modal" @submit.prevent="submit(false)"><header><div><small>{{detail.ruta}} · SECUENCIA {{detail.secuencia}}</small><h2>{{detail.cliente}}</h2><p>{{detail.direccion}}</p></div><button type="button" @click="close">×</button></header><section class="meter"><div><span>Medidor</span><b>{{detail.medidor}}</b></div><div><span>Lectura anterior</span><b>{{detail.lectura_anterior}}</b></div><div><span>Promedio</span><b>{{detail.consumo_promedio}} m³</b></div><div><span>Suministro</span><b>{{detail.suministro}}</b></div></section><template v-if="!detail.registrado"><div class="question"><h3>¿La lectura puede leerse claramente?</h3><button type="button" :class="{active:form.legible}" @click="form.legible=true">Sí, ingresar lectura</button><button type="button" :class="{active:!form.legible}" @click="form.legible=false">No se puede leer</button></div><label v-if="form.legible" class="big">Lectura actual *<input v-model="form.lectura" type="number" min="0"><small>Consumo calculado: {{consumption}} m³</small></label><label v-else>Impedimento *<select v-model="form.observacion_id"><option value="">Seleccione</option><option v-for="x in observaciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><p v-if="atypical" class="warning">Lectura fuera del rango esperado. Adjunte evidencia.</p><label>Fotografías {{!form.legible||atypical?'*':''}}<input type="file" accept="image/*" capture="environment" multiple @change="pick"><small>Máximo 5 · {{files.length}} seleccionada(s)</small></label><h3>Dinámica catastral</h3><div class="dynamics"><button v-for="x in dinamicas" :key="x.id" type="button" :class="{selected:form.dinamicas.includes(x.id)}" @click="toggle(x.id)">{{x.nombre}} {{form.dinamicas.includes(x.id)?'✓':''}}</button></div><label>Observación de campo<textarea v-model.trim="form.detalle" rows="2"></textarea></label><div class="gps"><span>GPS</span><b>{{form.latitud&&form.longitud?`${form.latitud}, ${form.longitud}`:'Esperando ubicación…'}}</b></div><footer><button type="button" class="clear" @click="close">Cancelar</button><button type="button" :disabled="saving" @click="submit(true)">Guardar y siguiente</button><button :disabled="saving">{{saving?'Guardando…':'Guardar lectura'}}</button></footer></template><template v-else><section class="detail"><div><span>Lectura tomada</span><b>{{detail.lectura_actual??'No registrada'}}</b></div><div><span>Consumo</span><b>{{detail.consumo??0}} m³</b></div><div><span>Fecha</span><b>{{detail.fecha_lectura}}</b></div><div><span>Lecturista</span><b>{{detail.lecturista}}</b></div><div><span>Observación</span><b>{{detail.observacion||'Sin observación'}}</b></div><div><span>Ubicación</span><b>{{detail.latitud}}, {{detail.longitud}}</b></div></section><div class="photos"><a v-for="(x,i) in detail.fotografias" :key="i" :href="x" target="_blank"><img :src="x" :alt="`Evidencia ${i+1}`"></a></div><footer><button type="button" class="clear" @click="close">Cerrar</button></footer></template></form></div></div></template>
<style scoped>
.page{--a:#227f62;color:#34464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-size:1.25rem;font-weight:800}.hero small,.modal small{color:var(--a);font-size:.53rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p,.modal header p{margin:0;color:#7c898f;font-size:.62rem}.advance{margin-left:auto;width:160px}.advance b,.advance span{display:block;font-size:.52rem}.advance i{height:5px;display:block;background:#dfe8e4}.advance em{height:100%;display:block;background:var(--a)}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.47rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters button,.pages button,.cards footer button,.modal footer button{padding:8px 11px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.49rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:14px;border-top:3px solid #d38a36;border-radius:8px;background:#fff}.cards article.done{border-color:var(--a)}.cards header{display:flex;justify-content:space-between;font-size:.45rem}.cards em{color:var(--a);font-style:normal}.cards h2{margin:10px 0 2px;font-size:.64rem}.cards>article>p{min-height:30px;color:#758289;font-size:.48rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:6px}.cards dt{color:#8a959a;font-size:.4rem}.cards dd{margin:2px 0;font-size:.48rem;font-weight:700}.reading{margin:9px 0;padding:8px;background:#edf8f3}.reading b,.reading span{display:block}.reading b{font-size:.8rem}.reading span{font-size:.43rem}.cards footer{display:flex;gap:5px}.cards footer button{flex:1}.cards footer .remove{background:#a3484b}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,820px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.meter,.detail{margin:13px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.meter div,.detail div,.gps{padding:9px;background:#f0f6f3}.meter span,.meter b,.detail span,.detail b,.gps span,.gps b{display:block;font-size:.47rem}.question{padding:11px;text-align:center;background:#f7f9f9}.question h3,.modal h3{font-size:.56rem}.question button,.dynamics button{padding:8px;border:1px solid #dce4e5;background:#fff;font-size:.48rem}.question button.active,.dynamics button.selected{color:#fff;background:var(--a)}.modal label{display:block;margin:10px 0;font-size:.48rem}.big input{font-size:1rem;font-weight:700}.big small,.modal label small{display:block;color:#7c898f;font-size:.43rem}.warning{padding:9px;color:#9a6220;background:#fff3dd;font-size:.5rem}.dynamics{display:grid;grid-template-columns:1fr 1fr}.dynamics button{text-align:left}.gps{margin:8px 0}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#65737a!important;background:#edf1f2!important}.photos{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.photos img{width:100%;height:120px;object-fit:cover}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}.filters{flex-wrap:wrap}.filters label{min-width:28%}.meter,.detail{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.advance{margin-left:0;width:100%}.filters{align-items:stretch;flex-direction:column}.filters label{width:100%}.cards,.meter,.detail,.dynamics{grid-template-columns:1fr}.modal footer{align-items:stretch;flex-direction:column}}
</style>
